package com.vibeguard.samples.consent; import jakarta.validation.Valid; import jakarta.validation.constraints.NotBlank; import java.time.*; import java.util.*; import java.util.concurrent.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/users/{userId}/consents") public class ConsentController {private final Map<String,List<Record>> history=new ConcurrentHashMap<>();@PostMapping public ResponseEntity<Record> update(@PathVariable String userId,@Valid @RequestBody Request request){Record record=new Record(request.purpose(),request.granted(),Instant.now());history.computeIfAbsent(userId,x->new ArrayList<>()).add(record);return ResponseEntity.status(201).body(record);}@GetMapping public List<Record> list(@PathVariable String userId){return List.copyOf(history.getOrDefault(userId,List.of()));}record Request(@NotBlank String purpose,boolean granted){}record Record(String purpose,boolean granted,Instant recordedAt){} }
